import { _decorator, Component, EventMouse, EventTouch, Input, input, UITransform, Vec2, Vec3,Node } from 'cc';
import type { Bus } from '../Engine/Bus';
import { HallEvents } from './HallEvents';


const { ccclass } = _decorator;

const TAP_TOLERANCE_SQ = 100;


@ccclass('HallInputHandler')
export class HallInputHandler extends Component {
    private _bus: Bus = null!;
    private _targetUITransform: UITransform = null!;

    private _isDragging = false;
    private _activeSource: 'none' | 'touch' | 'mouse' = 'none';

    private _touchesPts = new Map<number, Vec2>();
    private _gesture: 'none' | 'pan' | 'pinch' = 'none';
    
    // === 复用对象，零 GC，且命名精确 ===
    private _touchUIPos = new Vec2();      // 触摸/鼠标的屏幕绝对坐标
    private _startUIPos = new Vec2();      // 按下时的屏幕绝对坐标
    
    private _inputWorldPos = new Vec3();   // 准备转换的输入坐标
    private _targetLocalPos = new Vec3();  // 转换后的目标节点局部坐标

    setup(bus: Bus, targetNode: Node) {
        this._bus = bus;
        this._targetUITransform = targetNode.getComponent(UITransform)!;
        this._registerInputListeners();
    }


    onDestroy() {
        this._unregisterInputListeners();
    }

    private _registerInputListeners(): void {
        this.node.on(Input.EventType.TOUCH_START, this._onTouchStart, this);
        this.node.on(Input.EventType.TOUCH_MOVE, this._onTouchMove, this);
        this.node.on(Input.EventType.TOUCH_END, this._onTouchEnd, this);
        this.node.on(Input.EventType.TOUCH_CANCEL, this._onTouchEnd, this);

        this.node.on(Input.EventType.MOUSE_DOWN, this._onMouseDown, this);
        this.node.on(Input.EventType.MOUSE_MOVE, this._onMouseMove, this);
        this.node.on(Input.EventType.MOUSE_UP, this._onMouseUp, this);
    }

    private _unregisterInputListeners(): void {
        this.node.off(Input.EventType.TOUCH_START, this._onTouchStart, this);
        this.node.off(Input.EventType.TOUCH_MOVE, this._onTouchMove, this);
        this.node.off(Input.EventType.TOUCH_END, this._onTouchEnd, this);
        this.node.off(Input.EventType.TOUCH_CANCEL, this._onTouchEnd, this);

        this.node.off(Input.EventType.MOUSE_DOWN, this._onMouseDown, this);
        this.node.off(Input.EventType.MOUSE_MOVE, this._onMouseMove, this);
        this.node.off(Input.EventType.MOUSE_UP, this._onMouseUp, this);
    }

    
    // ===== 触摸 =====
      // ===== 触摸 =====
    private _onTouchStart(e: EventTouch): void {
        const p = this._syncPoint(e);
        if (this._touchesPts.size === 1) {
            this._gesture = 'pan';
            this._startUIPos.set(p.x, p.y);
        } else if (this._touchesPts.size === 2) {
            this._gesture = 'pinch';
            this._pinchLastDist = this._currentDist();
        }
        this._activeSource = 'touch';
        this._isDragging = true;
        e.getUILocation(this._touchUIPos);
        this._startUIPos.set(this._touchUIPos.x, this._touchUIPos.y);
    }

    private _onTouchMove(e: EventTouch): void {
        if (this._activeSource !== 'touch' || !this._isDragging || !this._bus) return;
        e.getUILocation(this._touchUIPos);
        this._emitDrag(this._touchUIPos.x, this._touchUIPos.y);
    }

    private _onTouchEnd(e: EventTouch): void {
        if (this._activeSource !== 'touch') return;
        this._isDragging = false;
        this._activeSource = 'none';
        e.getUILocation(this._touchUIPos);
        this._checkClickOrEndDrag(this._touchUIPos.x, this._touchUIPos.y);
    }

    // ===== 鼠标（同理） =====
    private _onMouseDown(e: EventMouse): void {
        if (e.getButton() !== EventMouse.BUTTON_LEFT) return;
        this._activeSource = 'mouse';
        this._isDragging = true;
        e.getUILocation(this._touchUIPos);
        this._startUIPos.set(this._touchUIPos.x, this._touchUIPos.y);
    }

    private _onMouseMove(e: EventMouse): void {
        if (this._activeSource !== 'mouse' || !this._isDragging || !this._bus) return;
        e.getUILocation(this._touchUIPos);
        this._emitDrag(this._touchUIPos.x, this._touchUIPos.y);
    }

    private _onMouseUp(e: EventMouse): void {
        if (e.getButton() !== EventMouse.BUTTON_LEFT || this._activeSource !== 'mouse') return;
        this._isDragging = false;
        this._activeSource = 'none';
        e.getUILocation(this._touchUIPos);
        this._checkClickOrEndDrag(this._touchUIPos.x, this._touchUIPos.y);
    }

    // ===== 核心转换逻辑 =====
    
        // 把转换逻辑提取出来
    private _convertToTargetLocal(uiX: number, uiY: number): void {
        this._inputWorldPos.set(uiX, uiY, 0);
        this._targetUITransform.convertToNodeSpaceAR(this._inputWorldPos, this._targetLocalPos);
    }

    private _emitDrag(uiX: number, uiY: number): void {
        this._convertToTargetLocal(uiX, uiY);
        this._bus.emit(HallEvents.INPUT_DRAG, this._targetLocalPos.x, this._targetLocalPos.y);
    }

    private _checkClickOrEndDrag(uiX: number, uiY: number): void {
        const dx = uiX - this._startUIPos.x;
        const dy = uiY - this._startUIPos.y;
        
        this._convertToTargetLocal(uiX, uiY);

        if (dx * dx + dy * dy < 100) { 
            this._bus.emit(HallEvents.INPUT_CLICK, this._targetLocalPos.x, this._targetLocalPos.y);
        } else {
            this._bus.emit(HallEvents.INPUT_DRAG_END, this._targetLocalPos.x, this._targetLocalPos.y);
        }
    }

    private _syncPoint(e: EventTouch): Vec2 {
        const id = e.getID();
        let p = this._touchesPts.get(id);
        if (!p) {
            p = new Vec2();
            this._touchesPts.set(id, p);
        } 
        e.getUILocation(p);
        return p;
    }
}